import copy
import json
import math
from pathlib import Path


def _reject_constant(value):
    raise ValueError(f"invalid JSON number: {value}")


def _object_pairs(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError(f"duplicate JSON key: {key}")
        result[key] = value
    return result


def _check_finite(value):
    if type(value) is float and not math.isfinite(value):
        raise ValueError("non-finite number")
    if type(value) is dict:
        for item in value.values():
            _check_finite(item)
    elif type(value) is list:
        for item in value:
            _check_finite(item)


def load_payload(path):
    path = Path(path)
    try:
        text = path.read_text(encoding="utf-8")
        value = json.loads(
            text,
            parse_constant=_reject_constant,
            object_pairs_hook=_object_pairs,
        )
    except (json.JSONDecodeError, UnicodeError) as error:
        raise ValueError(f"invalid JSON: {path}") from error
    if type(value) not in (dict, list):
        raise ValueError("JSON payload must be an object or array")
    _check_finite(value)
    return value


def is_number(value):
    return type(value) in (int, float) and math.isfinite(value)


def require_object(value):
    if type(value) is not dict:
        raise ValueError("payload must be an object")
    _check_finite(value)
    return value


def require_keys(value, keys):
    require_object(value)
    missing = [key for key in keys if key not in value]
    if missing:
        raise ValueError(f"missing required fields: {', '.join(missing)}")


def require_string(value, field):
    if type(value) is not str or not value.strip():
        raise ValueError(f"{field} must be a non-empty string")
    return value


def require_bool(value, field):
    if type(value) is not bool:
        raise ValueError(f"{field} must be a boolean")
    return value


def require_nonnegative_number(value, field):
    if not is_number(value) or value < 0:
        raise ValueError(f"{field} must be a non-negative finite number")
    return value


def require_unique_strings(value, field):
    if type(value) is not list:
        raise ValueError(f"{field} must be a list")
    seen = set()
    for item in value:
        require_string(item, f"{field} item")
        if item in seen:
            raise ValueError(f"{field} contains duplicate values")
        seen.add(item)
    return value


def validate_contract(payload, inputs_count=None):
    require_keys(payload, ("name", "operation", "inputs"))
    require_string(payload["name"], "contract name")
    require_string(payload["operation"], "contract operation")
    if type(payload["inputs"]) is not list:
        raise ValueError("contract inputs must be a list")
    for item in payload["inputs"]:
        require_safe_path(item)
    if inputs_count is not None and len(payload["inputs"]) != inputs_count:
        raise ValueError("payload count does not match contract inputs")
    return payload


def require_safe_path(value):
    if type(value) is not str or not value:
        raise ValueError("path must be a non-empty string")
    if "\\" in value or ":" in value:
        raise ValueError("unsafe path")
    parts = value.split("/")
    if value.startswith("/") or any(part in ("", ".", "..") for part in parts):
        raise ValueError("unsafe path")
    return value


def business_payload(payload):
    if type(payload) is dict and set(payload) == {"name", "result"}:
        return payload["result"]
    return payload


def unwrap_component(payload, expected_name):
    if type(payload) is not dict or set(payload) != {"name", "result"}:
        raise ValueError(f"input must be a {expected_name} component result")
    if payload["name"] != expected_name:
        raise ValueError(f"input must be a {expected_name} component result")
    return payload["result"]


def validate_fit_result(payload):
    require_keys(payload, ("classes", "sample_count", "members"))
    classes = require_unique_strings(payload["classes"], "classes")
    class_set = set(classes)
    sample_count = payload["sample_count"]
    if type(sample_count) is not int or sample_count < 0:
        raise ValueError("sample_count must be a non-negative integer")
    if type(payload["members"]) is not list:
        raise ValueError("members must be a list")

    member_ids = set()
    total_weight = 0.0
    for member in payload["members"]:
        require_keys(
            member,
            (
                "id",
                "active",
                "weight",
                "predictions",
                "classes",
                "probabilities",
                "fit_weight",
            ),
        )
        member_id = require_string(member["id"], "member id")
        if member_id in member_ids:
            raise ValueError("member ids must be unique")
        member_ids.add(member_id)
        require_bool(member["active"], "member active")
        if member["active"] is not True:
            raise ValueError("fit result must contain only active members")
        weight = require_nonnegative_number(member["weight"], "member weight")
        total_weight += weight

        member_classes = require_unique_strings(member["classes"], "member classes")
        if len(member_classes) != len(classes) or set(member_classes) != class_set:
            raise ValueError("member classes must be a permutation of global classes")
        if type(member["predictions"]) is not list or len(member["predictions"]) != sample_count:
            raise ValueError("member predictions must match sample_count")
        for prediction in member["predictions"]:
            if type(prediction) is not str or prediction not in class_set:
                raise ValueError("member prediction must be a global class")

        if type(member["probabilities"]) is not list or len(member["probabilities"]) != sample_count:
            raise ValueError("member probabilities must match sample_count")
        for row in member["probabilities"]:
            if type(row) is not list or len(row) != len(member_classes):
                raise ValueError("probability row length must match member classes")
            row_sum = 0.0
            for probability in row:
                if not is_number(probability) or probability < 0:
                    raise ValueError("probabilities must be non-negative finite numbers")
                row_sum += probability
            if abs(row_sum - 1.0) > 1e-9:
                raise ValueError("probability rows must sum to 1")

        fit_weight = member["fit_weight"]
        if type(fit_weight) is not list or len(fit_weight) != sample_count:
            raise ValueError("fit_weight must match sample_count")
        for item in fit_weight:
            require_nonnegative_number(item, "fit_weight item")

    if not payload["members"] or total_weight <= 0:
        raise ValueError("fit result requires active members with positive total weight")
    return classes, sample_count


def write_json(path, value):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    text = json.dumps(
        value,
        ensure_ascii=False,
        sort_keys=True,
        indent=2,
        allow_nan=False,
    ) + "\n"
    path.write_text(text, encoding="utf-8")


def deep_copy(value):
    return copy.deepcopy(value)

